/* Otthon dashboard 1.0.0 — independent of Fűtéstuning controls. */
(()=>{
const DEFAULT_LIGHTS=[
 {name:'Kanapé',entity:'switch.kanape_sonoff_10022d0f14_1',area:'Nappali',icon:'mdi:floor-lamp'},
 {name:'Cserépkályha',entity:'switch.cserepkalyha_sonoff_10022d0f04_1',area:'Nappali',icon:'mdi:lamp'},
 {name:'Medence',entity:'switch.medence_vilagitas_sonoff_10027529d7',area:'Kültér',icon:'mdi:pool'},
 {name:'Napozóterasz',entity:'switch.napozoterasz_vilagitas_sonoff_100275197e',area:'Kültér',icon:'mdi:weather-sunny'}];
const DEFAULT_GATES=[['Nagykapu','switch.nagykapu_sonoff_100186696c','Kapu cam'],['Lenti garázsajtó','switch.lenti_garazsajto_sonoff_1001de5ce9','Lenti garázs cam'],['Fenti garázsajtó','switch.fenti_garazsajto_sonoff_10018660b9','Fenti garázs cam'],['Fedett terasz garázsajtó','switch.fedett_terasz_garazsajto_sonoff_10016811d4',null]].map(([name,entity,camera_name])=>({name,entity,camera_name}));
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const css=`:host{display:block;min-width:0;color:#eef6fd;font:15px/1.35 system-ui,-apple-system,sans-serif}*{box-sizing:border-box}button,input{font:inherit}button{color:inherit;cursor:pointer}button:disabled{opacity:.5;cursor:default}button:focus-visible,input:focus-visible{outline:3px solid #70d9ff;outline-offset:3px}.root{background:radial-gradient(ellipse at top,#12324a,#071827 75%);border-radius:22px;padding:18px 22px;min-width:0}header{display:flex;align-items:center;gap:12px;margin-bottom:14px}h1{font-size:25px;margin:0;font-weight:600}small,.muted{color:#abc0d0;font-size:12px}h2{font-size:20px;margin:0 0 12px;font-weight:500}ha-icon{--mdc-icon-size:24px;flex:none}.brand{padding:11px;border-radius:14px;background:#19384f;color:#6dd5ff}nav{display:flex;gap:8px;margin-bottom:18px}nav button,.zone button,.action{background:#193247;border:0;border-radius:12px;padding:11px 16px;min-height:44px}nav button{display:flex;align-items:center;gap:8px}nav button[aria-selected=true]{background:#28506b}.sectionhead{display:flex;justify-content:space-between;align-items:center;margin:14px 0 8px;gap:8px}.sectionhead b{font-weight:500}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.tile{display:flex;align-items:center;gap:10px;text-align:left;min-width:0;min-height:88px;border:1px solid #30485b;border-radius:17px;background:#1b3042;padding:15px}.tile.on{background:#604c24;border-color:#a58440}.tile.on .symbol{color:#ffda83;background:#79602c}.tile.unavailable{border-style:dashed}.symbol{display:grid;place-items:center;background:#294458;border-radius:12px;width:36px;height:36px;flex:none}.name{display:block;font-weight:500;overflow-wrap:anywhere}.state{display:block;color:#d0dce6;font-size:12px;margin-top:3px}.reserved{min-height:44px;align-self:center;background:transparent;border:1px dashed #3b5264;border-radius:12px;padding:8px 12px;font-size:12px;color:#abc0d0}.zone{display:flex;gap:6px;margin-bottom:8px}.zone button{font-size:12px;padding:8px 14px}.zone [aria-pressed=true]{background:#33536b}.gategrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.gate{background:#1b3042;border-radius:17px;padding:14px;min-width:0}.camera{display:grid;place-content:center;text-align:center;background:#12293a;border-radius:11px;min-height:110px;color:#abc0d0;margin-bottom:10px;padding:8px}.camera button{background:none;border:0;color:inherit}.camera img{width:100%;max-height:170px;object-fit:cover;border-radius:10px}.gate .action{width:100%;margin-top:10px}.alarm-layout{display:grid;grid-template-columns:1fr 1fr;gap:20px}.alarm-box{background:#1b3042;border-radius:18px;padding:22px;text-align:center}.sensor{padding:12px 0;border-bottom:1px solid #30485b;display:flex;gap:10px;justify-content:space-between}.alarm-host{min-width:0}.notice{color:#ffdb8d;margin:8px 0;overflow-wrap:anywhere;font-size:13px}.notice:empty{display:none}footer{font-size:11px;color:#8fa9bc;margin-top:12px}.groupactions{display:flex;gap:6px}.groupactions button{font-size:12px;padding:8px 12px}.brightness{display:flex;gap:8px;align-items:center;font-size:12px;margin-top:5px}.brightness input{width:100%;min-width:0;min-height:44px}.tilewrap{min-width:0}.tilewrap>.tile{width:100%}@media(max-width:760px){.root{padding:14px;border-radius:16px}nav{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;margin-bottom:14px}nav button{flex-direction:column;text-align:center;font-size:12px;padding:10px 4px;gap:5px;min-height:64px}.grid,.gategrid{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.tile{min-height:90px;padding:11px;gap:8px}.symbol{width:30px;height:34px}.zone{display:grid;grid-template-columns:repeat(4,minmax(0,1fr))}.zone button{padding:8px 2px}.alarm-layout{grid-template-columns:1fr}.gate{padding:11px}.gate .action{font-size:12px;padding:8px}.name{font-size:14px}.reserved{min-height:44px;padding:8px;font-size:12px}.sectionhead{flex-wrap:wrap}h1{font-size:23px}}`;
class OtthonCard extends HTMLElement{
 constructor(){super();this.attachShadow({mode:'open'});this.page='lights';this.zone='Áttekintés';this.pending=false;this.message='';this.nativeAlarm=null;this.alarmKey='';}
 setConfig(c){this.cfg={...c};this.lights=c.lights||DEFAULT_LIGHTS;this.gates=c.gates||DEFAULT_GATES;this.render();}
 set hass(h){this._hass=h;this.render();if(this.nativeAlarm)this.nativeAlarm.hass=h;}
 getCardSize(){return 8;}
 static getStubConfig(){return {type:'custom:otthon-card'};}
 entity(id){return this._hass?.states?.[id];}
 available(id){const s=this.entity(id);return !!s&&!['unknown','unavailable'].includes(s.state);}
 icon(n){return `<ha-icon icon="${esc(n)}"></ha-icon>`;}
 more(id){this.dispatchEvent(new CustomEvent('hass-more-info',{detail:{entityId:id},bubbles:true,composed:true}));}
 async service(domain,action,data){if(this.pending)return;this.pending=true;this.message='';this.render();try{await this._hass.callService(domain,action,data);}catch(e){this.message='A parancs nem sikerült: '+(e?.message||String(e));}finally{this.pending=false;this.render();}}
 toggleLight(i){const x=this.lights[i];if(!x||!this.available(x.entity))return;const domain=x.entity.split('.')[0];if(!['light','switch'].includes(domain))return;return this.service(domain,this.entity(x.entity).state==='on'?'turn_off':'turn_on',{entity_id:x.entity});}
 group(on){const ids=this.lights.filter(x=>x.area==='Nappali').map(x=>x.entity);if(!ids.length||ids.some(id=>!this.available(id)))return;return this.service('homeassistant',on?'turn_on':'turn_off',{entity_id:ids});}
 lightTile(x,i){const s=this.entity(x.entity),ok=this.available(x.entity),on=s?.state==='on';const dim=x.entity.startsWith('light.')&&ok&&(s.attributes?.supported_color_modes||[]).some(m=>!['onoff','unknown'].includes(m));return `<div class="tilewrap"><button class="tile ${ok?(on?'on':''):'unavailable'}" data-light="${i}" aria-pressed="${on}" ${!ok||this.pending?'disabled':''}><span class="symbol">${this.icon(x.icon||'mdi:lightbulb')}</span><span><span class="name">${esc(x.name)}</span><span class="state">${ok?(on?'Bekapcsolva':'Kikapcsolva'):'Nem elérhető'}</span></span></button>${dim?`<label class="brightness">Fényerő<input type="range" min="1" max="100" value="${Math.max(1,Math.round((s.attributes.brightness||1)/2.55))}" data-dim="${i}" ${this.pending?'disabled':''}></label>`:''}</div>`;}
 lightsPage(){const reserve=n=>`<div class="reserved">+ Szabad ${n}</div>`;let n=0;const living=this.lights.filter(x=>x.area==='Nappali');const livingOK=living.length&&living.every(x=>this.available(x.entity));const count=living.filter(x=>this.entity(x.entity)?.state==='on').length;const groupState=!livingOK?'Nem elérhető':count===0?'Kikapcsolva':count===living.length?'Bekapcsolva':'Részben bekapcsolva';return `<h2>Világítás</h2><div class="zone">${['Áttekintés','Földszint','Emelet','Kültér'].map(z=>`<button data-zone="${z}" aria-pressed="${z===this.zone}">${z}</button>`).join('')}</div>${['Nappali','Kültér','További helyiségek'].filter(a=>this.zone==='Áttekintés'||(this.zone==='Földszint'&&a!=='Kültér')||(this.zone==='Kültér'&&a==='Kültér')||(this.zone==='Emelet'&&a==='További helyiségek')).map(a=>{const items=this.lights.map((x,i)=>({x,i})).filter(({x})=>x.area===a);const reserveCount=a==='További helyiségek'?4:Math.max(0,4-items.length);return `<section><div class="sectionhead"><b>${a}</b>${a==='Nappali'?`<span class="muted" data-group-state>${groupState}</span><span class="groupactions"><button class="action" data-group="on" ${!livingOK||this.pending?'disabled':''}>Összes be</button><button class="action" data-group="off" ${!livingOK||this.pending?'disabled':''}>Összes ki</button></span>`:''}</div><div class="grid">${items.map(({x,i})=>this.lightTile(x,i)).join('')}${Array.from({length:reserveCount},()=>reserve(++n)).join('')}</div></section>`}).join('')}`;}
 cameraId(g){if(g.camera)return this.entity(g.camera)&&g.camera.startsWith('camera.')?g.camera:null;const matches=Object.entries(this._hass?.states||{}).filter(([id,s])=>id.startsWith('camera.')&&g.camera_name&&s.attributes?.friendly_name===g.camera_name);return matches.length===1?matches[0][0]:null;}
 gatesPage(){return `<h2>Kapuk és kamerák</h2><div class="gategrid">${this.gates.map((g,i)=>{const cam=this.cameraId(g),cs=this.entity(cam);const picture=cs?.attributes?.entity_picture;const canView=this.available(cam)&&typeof picture==='string'&&picture.startsWith('/api/camera_proxy/');const position=this.entity(g.position_entity);const positionOK=this.available(g.position_entity);const status=positionOK?(position.state==='on'?'Nyitva':position.state==='off'?'Zárva':'Ismeretlen helyzet'):'Nincs helyzet-visszajelzés';const verified=g.verified_action&&['switch','button','cover'].includes(g.verified_action.domain)&&['turn_on','press','open_cover','close_cover','stop_cover'].includes(g.verified_action.service);return `<section class="gate"><div class="camera">${canView?`<button data-camera="${i}" aria-label="${esc(g.name)} kamera nagyítása"><img src="${esc(picture)}" alt="${esc(g.camera_name||g.name)}"></button>`:`${this.icon('mdi:video-off')}<span>${cam?'Kamera nem elérhető':'Kamera nincs beállítva'}</span>`}</div><span class="name">${esc(g.name)}</span><span class="state">${status}</span><button class="action" data-gate="${i}" ${!verified||!this.available(g.entity)||this.pending?'disabled':''}>${verified?'Kapuműködtetés':'Vezérlés ellenőrzésre vár'}</button></section>`}).join('')}</div>`;}
 alarmId(){return this.cfg?.alarm_entity||'alarm_control_panel.nspanelpronappali_sonoff_1002139b4c_alarm';}
 alarmPage(){const names=['Bejárat','Nappali','Konyha','Garázs','Hanna'];const ids=['bejarat','nappalli','konyha','garazs','hanna'].map(n=>`binary_sensor.${n}_mozgaserzekelo_occupancy`);return `<h2>Riasztó</h2><div class="alarm-layout"><div class="alarm-host">${this.available(this.alarmId())?'':'<div class="alarm-box">Riasztó nem elérhető</div>'}</div><section>${(this.cfg?.sensors||names.map((name,i)=>({name,entity:ids[i]}))).map(x=>`<div class="sensor"><span>${esc(x.name)}</span><span class="muted">${!this.available(x.entity)?'Nem elérhető':this.entity(x.entity).state==='on'?'Mozgás':'Nincs mozgás'}</span></div>`).join('')}</section></div>`;}
 async mountAlarm(){const id=this.alarmId();if(!this.available(id))return;const host=this.shadowRoot.querySelector('.alarm-host');if(!host)return;const key=id+JSON.stringify(this.entity(id)?.attributes?.supported_features);if(this.nativeAlarm&&this.alarmKey===key){this.nativeAlarm.hass=this._hass;host.append(this.nativeAlarm);return;}try{const helpers=await window.loadCardHelpers();if(this.page!=='alarm'||!this.isConnected)return;this.nativeAlarm=helpers.createCardElement({type:'alarm-panel',entity:id});this.alarmKey=key;this.nativeAlarm.hass=this._hass;this.shadowRoot.querySelector('.alarm-host')?.replaceChildren(this.nativeAlarm);}catch{if(this.page==='alarm'){const el=this.shadowRoot.querySelector('.alarm-host');if(el){el.innerHTML='<button class="action" data-more-alarm>Riasztó vezérlő megnyitása</button>';el.querySelector('button').onclick=()=>this.more(id);}}}}
 render(){if(!this.cfg)return;const pages=[['lights','Világítás','mdi:lightbulb-outline'],['gates','Kapuk és kamerák','mdi:video-outline'],['alarm','Riasztó','mdi:shield-home-outline']];this.shadowRoot.innerHTML=`<style>${css}</style><div class="root"><header><span class="brand">${this.icon('mdi:home-outline')}</span><div><h1>Otthon</h1><small>Világítás · Kapuk · Biztonság</small></div></header><nav aria-label="Otthon oldalak">${pages.map(([id,name,icon])=>`<button data-page="${id}" aria-selected="${this.page===id}">${this.icon(icon)}${name}</button>`).join('')}</nav><main>${this.page==='lights'?this.lightsPage():this.page==='gates'?this.gatesPage():this.alarmPage()}</main><p class="notice" role="status">${esc(this.message)}</p><footer>Otthon 1.0.0</footer></div>`;
 this.shadowRoot.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{this.page=b.dataset.page;this.message='';this.render();});
 this.shadowRoot.querySelectorAll('[data-zone]').forEach(b=>b.onclick=()=>{this.zone=b.dataset.zone;this.render();});
 this.shadowRoot.querySelectorAll('[data-light]').forEach(b=>b.onclick=()=>this.toggleLight(+b.dataset.light));
 this.shadowRoot.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>this.group(b.dataset.group==='on'));
 this.shadowRoot.querySelectorAll('[data-dim]').forEach(b=>b.onchange=()=>{const x=this.lights[+b.dataset.dim];if(this.available(x.entity))this.service('light','turn_on',{entity_id:x.entity,brightness_pct:Number(b.value)});});
 this.shadowRoot.querySelectorAll('[data-camera]').forEach(b=>b.onclick=()=>this.more(this.cameraId(this.gates[+b.dataset.camera])));
 this.shadowRoot.querySelectorAll('[data-gate]').forEach(b=>b.onclick=()=>{const g=this.gates[+b.dataset.gate];if(!g.verified_action||!this.available(g.entity))return;if(window.confirm(g.name+' működtetése?'))this.service(g.verified_action.domain,g.verified_action.service,{entity_id:g.entity});});
 if(this.page==='alarm')this.mountAlarm();
 }
}
if(!customElements.get('otthon-card'))customElements.define('otthon-card',OtthonCard);
window.customCards=window.customCards||[];
if(!window.customCards.some(x=>x.type==='otthon-card'))window.customCards.push({type:'otthon-card',name:'Otthon',description:'Világítás, kapuk és riasztó — iPad / iPhone',preview:false});
})();
